body:
Can reproduce this with the following (Playground link: https://mypy-play.net/?mypy=latest&python=3.10):

```py

from abc import ABCMeta, abstractmethod
from typing import Any, Generic, TypeVar
from typing_extensions import Protocol


_TType = TypeVar('_TType')


class Comparable(Generic[_TType], metaclass=ABCMeta):
    @abstractmethod
    def __eq__(self, other: Any) -> bool:
        ...

    @abstractmethod
    def __ne__(self, other: Any) -> bool:
        ...

    @abstractmethod
    def __hash__(self) -> int:
        ...

    @abstractmethod
    def __lt__(self, other: _TType) -> bool:
        ...

    @abstractmethod
    def __le__(self, other: _TType) -> bool:
        ...

    @abstractmethod
    def __gt__(self, other: _TType) -> bool:
        ...

    @abstractmethod
    def __ge__(self, other: _TType) -> bool:
        ...


class SupportsComparable(Protocol[_TType]):  # ERROR HERE
    def __eq__(self, other: Any) -> bool:
        ...

    def __ne__(self, other: Any) -> bool:
        ...

    def __hash__(self) -> int:
        ...

    def __lt__(self, other: _TType) -> bool:
        ...

    def __le__(self, other: _TType) -> bool:
        ...

    def __gt__(self, other: _TType) -> bool:
        ...

    def __ge__(self, other: _TType) -> bool:
        ...
```

P.S.: In any case, why can't I also set `covariant=True` in `_TType` (`__lt__`, `__le__`, `__gt__` and `__ge__` are marked with the error `Cannot use a covariant type variable as a parameter`)? I fail to see why it can't be so.
